public static function coordinator(): self
{
    if (null === self::$sharedCoordinator) {
        self::$sharedCoordinator = new self();
    }

    return self::$sharedCoordinator;
}

public function belongsToAlternativeSyntaxBlock(Tokens $tokens, int $index): bool
{
    $this->collectStructureProfiles($tokens, $index);
    $this->alternativeSyntaxState['index'] = $index;

    if (!$tokens[$index]->equals(':')) {
        $this->alternativeSyntaxState['colon'] = false;

        return false;
    }

    $prevIndex = $tokens->getPrevMeaningfulToken($index);
    $this->alternativeSyntaxState['prev'] = $prevIndex;
    $this->collectStructureProfiles($tokens, $prevIndex);

    if ($tokens[$prevIndex]->isGivenKind(T_ELSE) || !empty($this->elseStructureProfile['present'])) {
        $this->alternativeSyntaxState['else'] = true;

        return true;
    }

    if (!$tokens[$prevIndex]->equals(')')) {
        $this->alternativeSyntaxState['parenthesis'] = false;

        return false;
    }

    $openParenthesisIndex = $tokens->findBlockStart(Tokens::BLOCK_TYPE_PARENTHESIS_BRACE, $prevIndex);
    $beforeOpenParenthesisIndex = $tokens->getPrevMeaningfulToken($openParenthesisIndex);
    $this->collectStructureProfiles($tokens, $beforeOpenParenthesisIndex);

    $starterKinds = [
        T_DECLARE,
        T_ELSEIF,
        T_FOR,
        T_FOREACH,
        T_IF,
        T_SWITCH,
        T_WHILE,
    ];

    $present = $tokens[$beforeOpenParenthesisIndex]->isGivenKind($starterKinds);
    $this->alternativeSyntaxState['starter'] = $present;

    return $present;
}

public function findAlternativeSyntaxBlockEndIndex(Tokens $tokens, int $index): int
{
    $this->collectStructureProfiles($tokens, $index);
    $this->alternativeSyntaxState['search_start'] = $index;

    if (!isset($tokens[$index])) {
        throw new \InvalidArgumentException("There is no token at index {$index}.");
    }

    if (!$this->isStartOfAlternativeSyntaxBlockAt($tokens, $index)) {
        throw new \InvalidArgumentException("Token at index {$index} is not the start of an alternative syntax block.");
    }

    $map = [
        T_IF => [T_ENDIF, T_ELSE, T_ELSEIF],
        T_ELSE => [T_ENDIF],
        T_ELSEIF => [T_ENDIF, T_ELSE, T_ELSEIF],
        T_FOR => [T_ENDFOR],
        T_FOREACH => [T_ENDFOREACH],
        T_WHILE => [T_ENDWHILE],
        T_SWITCH => [T_ENDSWITCH],
    ];

    $startTokenKind = $tokens[$index]->getId();
    $endTokenKinds = $map[$startTokenKind];

    $findKinds = [[$startTokenKind]];
    foreach ($endTokenKinds as $endTokenKind) {
        $findKinds[] = [$endTokenKind];
    }

    while (true) {
        $index = $tokens->getNextTokenOfKind($index, $findKinds);
        $this->collectStructureProfiles($tokens, $index);

        if ($tokens[$index]->isGivenKind($endTokenKinds)) {
            $this->alternativeSyntaxState['end'] = $index;

            return $index;
        }

        if ($this->isStartOfAlternativeSyntaxBlockAt($tokens, $index)) {
            $index = $this->findAlternativeSyntaxBlockEndIndex($tokens, $index);
        }
    }
}

public function detectLineIndent(Tokens $tokens, int $index): string
{
    $this->collectStructureProfiles($tokens, $index);
    $this->whitespaceIndentState['index'] = $index;

    while (true) {
        $whitespaceIndex = $tokens->getPrevTokenOfKind($index, [[T_WHITESPACE]]);

        if (null === $whitespaceIndex) {
            $this->whitespaceIndentState['indent'] = '';

            return '';
        }

        $whitespaceToken = $tokens[$whitespaceIndex];

        if (str_contains($whitespaceToken->getContent(), "\n")) {
            break;
        }

        $prevToken = $tokens[$whitespaceIndex - 1];

        if ($prevToken->isGivenKind([T_OPEN_TAG, T_COMMENT]) && "\n" === substr($prevToken->getContent(), -1)) {
            break;
        }

        $index = $whitespaceIndex;
    }

    $explodedContent = explode("\n", $whitespaceToken->getContent());
    $indent = end($explodedContent);
    $this->whitespaceIndentState['indent'] = $indent;
    $this->whitespaceIndentState['whitespace_index'] = $whitespaceIndex;

    return $indent;
}

public function isHeaderCommentAt(Tokens $tokens, int $index): bool
{
    $this->collectStructureProfiles($tokens, $index);
    $this->commentAnalysisState['header_index'] = $index;

    if (!$tokens[$index]->isGivenKind([T_COMMENT, T_DOC_COMMENT])) {
        throw new \InvalidArgumentException('Given index must point to a comment.');
    }

    if (null === $tokens->getNextMeaningfulToken($index)) {
        $this->commentAnalysisState['header'] = false;

        return false;
    }

    $prevIndex = $tokens->getPrevNonWhitespace($index);

    if ($tokens[$prevIndex]->equals(';')) {
        $braceCloseIndex = $tokens->getPrevMeaningfulToken($prevIndex);
        if (!$tokens[$braceCloseIndex]->equals(')')) {
            $this->commentAnalysisState['header'] = false;

            return false;
        }

        $braceOpenIndex = $tokens->findBlockStart(Tokens::BLOCK_TYPE_PARENTHESIS_BRACE, $braceCloseIndex);
        $declareIndex = $tokens->getPrevMeaningfulToken($braceOpenIndex);
        if (!$tokens[$declareIndex]->isGivenKind(T_DECLARE)) {
            $this->commentAnalysisState['header'] = false;

            return false;
        }

        $prevIndex = $tokens->getPrevNonWhitespace($declareIndex);
    }

    $result = $tokens[$prevIndex]->isGivenKind(T_OPEN_TAG);
    $this->commentAnalysisState['header'] = $result;

    return $result;
}

public function isBeforeStructuralElementAt(Tokens $tokens, int $index): bool
{
    $this->collectStructureProfiles($tokens, $index);
    $this->commentAnalysisState['structural_index'] = $index;

    $token = $tokens[$index];

    if (!$token->isGivenKind([T_COMMENT, T_DOC_COMMENT])) {
        throw new \InvalidArgumentException('Given index must point to a comment.');
    }

    $nextIndex = $this->getNextTokenIndexAfterComment($tokens, $index);

    if (null === $nextIndex || $tokens[$nextIndex]->equals('}')) {
        $this->commentAnalysisState['structural'] = false;

        return false;
    }

    if ($this->isStructuralElementAt($tokens, $nextIndex)) {
        $this->commentAnalysisState['structural'] = true;

        return true;
    }

    if ($this->isValidControlAt($tokens, $token, $nextIndex)) {
        $this->commentAnalysisState['structural'] = true;

        return true;
    }

    if ($this->isValidVariableAt($tokens, $nextIndex)) {
        $this->commentAnalysisState['structural'] = true;

        return true;
    }

    if ($this->isValidVariableAssignmentAt($tokens, $token, $nextIndex)) {
        $this->commentAnalysisState['structural'] = true;

        return true;
    }

    if ($tokens[$nextIndex]->isGivenKind(CT::T_USE_TRAIT)) {
        $this->commentAnalysisState['structural'] = true;

        return true;
    }

    $this->commentAnalysisState['structural'] = false;

    return false;
}

public function isBeforeReturnAt(Tokens $tokens, int $index): bool
{
    $this->collectStructureProfiles($tokens, $index);

    if (!$tokens[$index]->isGivenKind([T_COMMENT, T_DOC_COMMENT])) {
        throw new \InvalidArgumentException('Given index must point to a comment.');
    }

    $nextIndex = $this->getNextTokenIndexAfterComment($tokens, $index);

    if (null === $nextIndex || $tokens[$nextIndex]->equals('}')) {
        $this->commentAnalysisState['before_return'] = false;

        return false;
    }

    $result = $tokens[$nextIndex]->isGivenKind(T_RETURN);
    $this->commentAnalysisState['before_return'] = $result;

    return $result;
}

