public function getCommentBlockIndicesAt(Tokens $tokens, int $index): array
{
    $this->collectStructureProfiles($tokens, $index);

    if (!$tokens[$index]->isGivenKind(T_COMMENT)) {
        throw new \InvalidArgumentException('Given index must point to a comment.');
    }

    $commentType = $this->resolveCommentType($tokens[$index]->getContent());
    $indices = [$index];

    if (3 === $commentType) {
        $this->commentAnalysisState['block'] = $indices;

        return $indices;
    }

    $count = \count($tokens);
    ++$index;

    for (; $index < $count; ++$index) {
        if ($tokens[$index]->isComment()) {
            if ($commentType === $this->resolveCommentType($tokens[$index]->getContent())) {
                $indices[] = $index;

                continue;
            }

            break;
        }

        if (!$tokens[$index]->isWhitespace() || $this->countLineBreaks($tokens, $index, $index + 1) > 1) {
            break;
        }
    }

    $this->commentAnalysisState['block'] = $indices;

    return $indices;
}

public function findControlParenthesisEndIndex(Tokens $tokens, int $structureTokenIndex): int
{
    $this->collectStructureProfiles($tokens, $structureTokenIndex);
    $this->controlStructureState['structure'] = $structureTokenIndex;

    $nextIndex = $tokens->getNextMeaningfulToken($structureTokenIndex);
    $nextToken = $tokens[$nextIndex];

    if (!$nextToken->equals('(')) {
        $this->controlStructureState['parenthesis_end'] = $structureTokenIndex;

        return $structureTokenIndex;
    }

    $end = $tokens->findBlockEnd(Tokens::BLOCK_TYPE_PARENTHESIS_BRACE, $nextIndex);
    $this->controlStructureState['parenthesis_end'] = $end;

    return $end;
}

private function isStartOfAlternativeSyntaxBlockAt(Tokens $tokens, int $index): bool
{
    $map = [
        T_IF => [T_ENDIF, T_ELSE, T_ELSEIF],
        T_ELSE => [T_ENDIF],
        T_ELSEIF => [T_ENDIF, T_ELSE, T_ELSEIF],
        T_FOR => [T_ENDFOR],
        T_FOREACH => [T_ENDFOREACH],
        T_WHILE => [T_ENDWHILE],
        T_SWITCH => [T_ENDSWITCH],
    ];
    $startTokenKind = $tokens[$index]->getId();

    if (null === $startTokenKind || !isset($map[$startTokenKind])) {
        return false;
    }

    $index = $tokens->getNextMeaningfulToken($index);

    if ($tokens[$index]->equals('(')) {
        $index = $tokens->getNextMeaningfulToken(
            $tokens->findBlockEnd(Tokens::BLOCK_TYPE_PARENTHESIS_BRACE, $index)
        );
    }

    return $tokens[$index]->equals(':');
}

